**Modular Web Application Firewall (WAF) in C#**
=====================================================

This C# implementation provides a modular Web Application Firewall (WAF) that consists of three primary components:
1.  **HTTP Request Inspector**: Parses HTTP request headers, query strings, and body payloads for SQL injection signatures.
2.  **Rate Limiting and IP Reputation Engine**: Tracks sliding window request counts per client IP to prevent brute-force attacks.
3.  **Incident Response Subsystem**: Logs violations and triggers automated firewall block rules.

### HTTP Request Inspector

The HTTP Request Inspector module is responsible for parsing HTTP requests and detecting potential SQL injection attacks.

```csharp
using System;
using System.Text.RegularExpressions;

public class HttpRequestInspector
{
    // Define SQL injection signature patterns
    private readonly string[] _sqlInjectionPatterns = new[]
    {
        @"SELECT|INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|TRUNCATE",
        @"UNION|OR|AND",
        @"LIKE|RLIKE|NOT LIKE|NOT RLIKE",
        @"LIMIT|OFFSET",
        @"ORDER BY",
        @"COUNT|SUM|AVG|MAX|MIN",
        @"JOIN|LEFT JOIN|RIGHT JOIN|FULL OUTER JOIN"
    };

    public bool InspectRequest(HttpRequest request)
    {
        // Check request headers for SQL injection patterns
        foreach (var header in request.Headers)
        {
            foreach (var pattern in _sqlInjectionPatterns)
            {
                if (Regex.IsMatch(header.Value, pattern, RegexOptions.IgnoreCase))
                {
                    return true; // Potential SQL injection detected
                }
            }
        }

        // Check query string for SQL injection patterns
        var queryString = $"{request.Url.Scheme}://{request.Url.Host}{request.Url.AbsolutePath}";
        foreach (var pattern in _sqlInjectionPatterns)
        {
            if (Regex.IsMatch(queryString, pattern, RegexOptions.IgnoreCase))
            {
                return true; // Potential SQL injection detected
            }
        }

        // Check request body for SQL injection patterns
        if (request.Method == HttpMethod.Post || request.Method == HttpMethod.Put)
        {
            var requestBody = request.Content.ReadAsStringAsync().Result;
            foreach (var pattern in _sqlInjectionPatterns)
            {
                if (Regex.IsMatch(requestBody, pattern, RegexOptions.IgnoreCase))
                {
                    return true; // Potential SQL injection detected
                }
            }
        }

        return false; // No potential SQL injection detected
    }
}
```

### Rate Limiting and IP Reputation Engine

The Rate Limiting and IP Reputation Engine module tracks sliding window request counts per client IP to prevent brute-force attacks.

```csharp
using System;
using System.Net;
using System.Threading;

public class RateLimitingAndIpReputationEngine
{
    private readonly Dictionary<IPAddress, int> _ipRequestCounts = new Dictionary<IPAddress, int>();
    private readonly int _maxRequestsPerWindow = 10;
    private readonly TimeSpan _windowDuration = TimeSpan.FromMinutes(1);

    public bool IsIpAllowed(IPAddress ip)
    {
        // Check if IP is in the dictionary
        if (!_ipRequestCounts.TryGetValue(ip, out var requestCount))
        {
            // Initialize IP request count and add to dictionary
            _ipRequestCounts[ip] = 1;
            return true;
        }

        // Check if request count exceeds the maximum allowed per window
        if (requestCount >= _maxRequestsPerWindow)
        {
            // Check if the window duration has passed since the last request
            var lastRequestTime = DateTime.Now - _windowDuration;
            var IPsToRemove = _ipRequestCounts.Where(x => x.Value <= _maxRequestsPerWindow && x.Key < ip).Select(x => x.Key);

            foreach (var ipToRemove in IPsToRemove)
            {
                _ipRequestCounts.Remove(ipToRemove);
            }

            if (_ipRequestCounts.TryGetValue(ip, out requestCount))
            {
                if (requestCount > _maxRequestsPerWindow)
                {
                    return false; // IP has exceeded the maximum allowed requests per window
                }
            }
        }

        // Increment request count for IP
        _ipRequestCounts[ip] = requestCount + 1;

        return true;
    }
}
```

### Incident Response Subsystem

The Incident Response Subsystem module logs violations and triggers automated firewall block rules.

